// three nested Menger sponges, smooth-unioned, then smoothly cut by a box -- scenes/menger.js as it was
// iterations is a compile-time u32: it is sdMenger's loop bound, and the compiler must see it to unroll the loop
let s = scale;
let s2 = s * 1.2;
let s3 = s * 1.8;
const it = iterations;
const it2 = max(iterations - 1u, 1u);
let bl = max(smoothing, 0.0001);
var frac = sdMenger(p / s, it) * s;
let frac2 = sdMenger(p / s2 - VEC3(1.0, 0.0, 0.0), it2) * s2;
frac = opSmoothUnion(frac, frac2, bl);
let frac3 = sdMenger(p / s3 - VEC3(1.0, 1.0, 0.0), it2) * s3;
frac = opSmoothUnion(frac, frac3, bl);
let b2 = sdBox(p / s, VEC3(carve)) * s;
frac = opSmoothSubtract(b2, frac, bl);
C = add_new(C, frac, MATERIAL);
